<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Booking - CozyCafe</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= e(BASE_URL) ?>/assets/css/style.css"></head><body><?php require dirname(__DIR__) . '/layouts/admin_header.php'; ?><?php require dirname(__DIR__) . '/layouts/admin_sidebar.php'; ?>
<main class="admin-main container-fluid p-4"><h1 class="h3 mb-4">Kelola Booking</h1><?php if ($flash): ?><div class="alert alert-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<form class="card border-0 shadow-sm p-3 mb-4 row g-2 mx-0" method="get"><div class="col-md-4"><input class="form-control" type="date" name="date" value="<?= e($_GET['date'] ?? '') ?>"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">Semua status</option><?php foreach (['Dikonfirmasi','Dibatalkan','Selesai'] as $value): ?><option <?= ($_GET['status']??'')==$value?'selected':'' ?>><?= e($value) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-coffee w-100">Filter</button></div></form>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Meja</th><th>Tanggal/Jam</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><?= e($booking['transaction_code']) ?></td><td><?= e($booking['customer_name']) ?></td><td><?= e($booking['table_number']) ?> · <?= e($booking['area']) ?></td><td><?= format_tanggal($booking['booking_date']) ?><br><?= format_waktu($booking['start_time']) ?>–<?= format_waktu($booking['end_time']) ?></td><td><?= e($booking['status']) ?></td><td><?php if ($booking['status']==='Dikonfirmasi'): ?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="finish"><input type="hidden" name="booking_id" value="<?= e($booking['id']) ?>"><button class="btn btn-sm btn-outline-coffee">Selesai</button></form><form method="post" class="d-inline mt-2"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="booking_id" value="<?= e($booking['id']) ?>"><input class="form-control form-control-sm d-inline-block mt-1" name="reason" placeholder="Alasan wajib" required><button class="btn btn-sm btn-danger mt-1">Batalkan</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
</main><?php require dirname(__DIR__) . '/layouts/admin_footer.php'; ?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="<?= e(BASE_URL) ?>/assets/js/app.js"></script></body></html>
